CREATE PROCEDURE CLAIMS.TEST_UNDECLARED_SYMBOLS (
    IN P_FLAG INTEGER,
    OUT P_RESULT VARCHAR(20),
    OUT P_AUDIT_REF BIGINT
)
LANGUAGE SQL
BEGIN
    DECLARE V_OK INTEGER DEFAULT 1;

    SELECT COUNT(*)
      INTO V_MISSING_COUNT
      FROM CLAIM
     WHERE STATUS = 'OPEN';

    IF P_FLAG = 1 THEN
        SET P_RESULT = 'INDEPENDENT';
    ELSEIF V_MISSING_COUNT > 0 THEN
        SET P_RESULT = 'DEPENDENT';
    ELSE
        SET P_RESULT = 'FALLBACK';
    END IF;

    BEGIN
        DECLARE V_INNER_ONLY INTEGER DEFAULT 7;
        SET V_OK = V_INNER_ONLY;
    END;

    SET V_OK = V_INNER_ONLY;
    SET P_AUDIT_REF = NEXT VALUE FOR AUDIT_SEQ;
END
